import{_ as o,c as a,o as l,ag as e}from"./chunks/framework.3IuuWm4t.js";const b=JSON.parse('{"title":"Halo 网页版配置指南","description":"","frontmatter":{},"headers":[],"relativePath":"platforms/custom-haloweb.md","filePath":"platforms/custom-haloweb.md","lastUpdated":1795234250000}'),r={name:"platforms/custom-haloweb.md"};function i(d,t,s,n,h,c){return l(),a("div",null,[...t[0]||(t[0]=[e('<h1 id="halo-网页版配置指南" tabindex="-1">Halo 网页版配置指南 <a class="header-anchor" href="#halo-网页版配置指南" aria-label="Permalink to &quot;Halo 网页版配置指南&quot;">​</a></h1><p>通过 <strong>Cookie 授权</strong>发布到 <strong>Halo 2.20+</strong>。图片默认走「当前平台」（Halo 附件库）。</p><h2 id="一、准备" tabindex="-1">一、准备 <a class="header-anchor" href="#一、准备" aria-label="Permalink to &quot;一、准备&quot;">​</a></h2><ol><li>一个 Halo 2.20+ 站点（含后台登录账号）。</li><li>在浏览器登录 Halo 后台。</li></ol><h2 id="二、配置" tabindex="-1">二、配置 <a class="header-anchor" href="#二、配置" aria-label="Permalink to &quot;二、配置&quot;">​</a></h2><table tabindex="0"><thead><tr><th>字段</th><th>填什么</th></tr></thead><tbody><tr><td>平台首页</td><td>Halo 博客首页完整地址，如 <code>https://yourhalo.com</code></td></tr><tr><td>API 地址</td><td>通常和首页地址相同</td></tr><tr><td>Cookie</td><td>点「1 去登录」登录后关闭窗口，再点「2 自动读取 Cookie」；也可展开「手动编辑」直接粘贴</td></tr><tr><td>预览规则</td><td>查看文章链接模板，默认 <code>/archives/{slug}</code></td></tr><tr><td>发布格式</td><td>默认 HTML</td></tr><tr><td>图床</td><td>默认「当前平台」（Halo 附件库）；不需要上传图片时可选「不使用」</td></tr></tbody></table><blockquote><p>⚠️ 必须先填「平台首页」完整 URL，再点登录/读取 Cookie；否则会提示 <code>Invalid URL</code>。</p></blockquote><h2 id="三、验证与发布" tabindex="-1">三、验证与发布 <a class="header-anchor" href="#三、验证与发布" aria-label="Permalink to &quot;三、验证与发布&quot;">​</a></h2><ol><li>点「1 去登录」→ 自动打开 Halo 登录页 → 用后台账号登录 → <strong>关闭窗口</strong>（关闭时保存 Cookie）。</li><li>点「2 自动读取 Cookie」→ 验证 → 账号状态「运行中」。</li><li>快速发布 → 选 Halo网页版 → 发布。</li></ol><h2 id="四、题头图与图片复用" tabindex="-1">四、题头图与图片复用 <a class="header-anchor" href="#四、题头图与图片复用" aria-label="Permalink to &quot;四、题头图与图片复用&quot;">​</a></h2><ul><li>封面按「思源题头图链接 → 正文首图链接 → 自定义上传」的顺序解析；前两者直接使用链接，不额外上传图片。</li><li>题头图不会再出现在正文首图；发布表单里的「封面图」可填写链接或上传自定义图片，主动选择会优先于自动解析。</li><li>没有题头图、正文首图或自定义封面时，更新会保留 Halo 端现有封面。</li><li>正文图片按内容复用已上传的 Halo 附件：重复更新不会重复上传；图片内容变化或附件被删除时会重新上传。</li></ul><h2 id="常见问题" tabindex="-1">常见问题 <a class="header-anchor" href="#常见问题" aria-label="Permalink to &quot;常见问题&quot;">​</a></h2><ul><li><strong>提示「Invalid URL」</strong>：先填完整站点地址，再点登录/读取 Cookie。</li><li><strong>Halo 版本要求</strong>：需 2.20 及以上。</li><li><strong>验证报「接口返回异常/登录状态可能已失效」</strong>：Cookie 过期或 Halo 重启导致会话失效，重新登录读取 Cookie。</li><li><strong>图片图床</strong>：默认「当前平台」即可；需要与思源一致的图床时可改选 PicGo。</li><li><strong>文章别名和站点设置不一致</strong>：新建文章时会读取 Halo 的「别名生成策略」（按标题 / 时间戳 / Short UUID / UUID）生成默认别名；发布页手动修改的别名优先。更新已发布文章沿用原别名，避免链接变化。</li></ul>',13)])])}const m=o(r,[["render",i]]);export{b as __pageData,m as default};
